<script setup lang="ts">
import type { SystemSettings } from '#shared/types'
interface SettingsView { settings: SystemSettings; kernel: { version: string | null; upstreamCommit: string | null; cliVersion: string | null } }
useHead({ title: '系统设置 · Command Code Manager' })
const api = useRequestFetch()
const { data, pending, error, refresh } = await useFetch<SettingsView>('/api/settings')
const form = ref<SystemSettings | null>(null)
watch(data, value => { if (value && !form.value) form.value = { ...value.settings } }, { immediate: true })
const dirty = computed(() => !!data.value && !!form.value && JSON.stringify(form.value) !== JSON.stringify(data.value.settings))
const { busy, run } = useApiAction()
async function save() {
  if (!form.value) return
  const result = await run(() => api<SettingsView>('/api/settings', { method: 'PATCH', body: { ...form.value } }), '系统设置已保存')
  if (result.ok) { form.value = { ...result.value.settings }; await refresh() }
}
useLiveRefresh(refresh)
</script>
<template>
  <AppPageHeader title="系统设置" description="调整调度、同步与日志保存参数，查看当前固定的内核版本。"><button class="button" :disabled="pending" @click="refresh()"><UIcon name="i-ph-arrow-clockwise-bold" :class="{ spinning: pending }" />重新读取</button><button v-if="form" form="settings-form" class="button primary" :disabled="busy || !dirty"><UIcon v-if="busy" name="i-ph-circle-notch-bold" class="spinning" />保存设置</button></AppPageHeader><AppState v-if="error" :error="error" @retry="refresh()" /><AppState v-else-if="!data || !form" :loading="pending" /><template v-else><form id="settings-form" class="settings-form" @submit.prevent="save"><fieldset :disabled="busy"><section class="settings-section"><div class="settings-description"><UIcon name="i-ph-git-branch-bold" /><h2>请求调度</h2><p>这些数值是本系统的运行配置，不是上游官方限制。</p></div><div class="settings-fields"><label class="field"><span>全局并发上限</span><input v-model.number="form.globalConcurrency" type="number" required min="1" max="1000" step="1"><small>所有账号合计允许同时转发的请求数。</small></label><label class="field"><span>新账号默认并发上限</span><input v-model.number="form.defaultAccountConcurrency" type="number" required min="1" max="100" step="1"><small>单个账号可以在详情页单独调整。</small></label><label class="field"><span>会话亲和保留时间 <small>秒</small></span><input v-model.number="form.affinityTtlSeconds" type="number" required min="60" max="604800" step="1"><small>保留会话与账号绑定的时间。</small></label><label class="field"><span>单次请求体上限 <small>MB</small></span><input v-model.number="form.maxRequestBodyMb" type="number" required min="1" max="64" step="1"><small>限制模型请求中提交的内容大小。</small></label></div></section><section class="settings-section"><div class="settings-description"><UIcon name="i-ph-arrows-clockwise-bold" /><h2>账号同步</h2><p>刷新实际额度与账号状态。失败会记录原因，已有快照保留获取时间。</p></div><div class="settings-fields"><label class="field"><span>活跃账号刷新间隔 <small>秒</small></span><input v-model.number="form.activeRefreshSeconds" type="number" required min="15" max="3600" step="1"></label><label class="field"><span>闲置账号刷新间隔 <small>秒</small></span><input v-model.number="form.idleRefreshSeconds" type="number" required min="60" max="86400" step="1"></label><label class="field"><span>活跃账号判断窗口 <small>秒</small></span><input v-model.number="form.activeWindowSeconds" type="number" required min="60" max="86400" step="1"><small>此时间内有实际调用的账号视为活跃。</small></label><label class="field"><span>同步任务并发数</span><input v-model.number="form.refreshConcurrency" type="number" required min="1" max="10" step="1"></label><label class="field"><span>每秒最多查询请求数</span><input v-model.number="form.refreshRatePerSecond" type="number" required min="1" max="20" step="1"><small>一次账号同步会发出多个官方查询请求；此处限制每秒查询请求数，不改变模型转发并发上限。</small></label></div></section><section class="settings-section"><div class="settings-description"><UIcon name="i-ph-clock-countdown-bold" /><h2>日志保留</h2><p>保存请求元数据及请求、回复内容，用于查看实际调用情况。</p></div><div class="settings-fields"><label class="field"><span>日志保留期限 <small>天</small></span><input v-model.number="form.logRetentionDays" type="number" required min="1" max="365" step="1"><small>超过期限的日志会按清理任务删除，调整后请留意历史记录范围。</small></label></div></section></fieldset><div class="settings-save-bar"><span>{{ dirty ? '设置有未保存的修改' : '当前设置已保存' }}</span><div class="inline-actions"><button type="button" class="button" :disabled="busy || !dirty" @click="form = { ...data.settings }">还原修改</button><button class="button primary" :disabled="busy || !dirty">保存设置</button></div></div></form><section class="panel kernel-panel"><div class="panel-heading"><h2><UIcon name="i-ph-package-bold" />内核版本</h2><span class="status-badge neutral">固定版本</span></div><dl class="kernel-fields"><div><dt>内核版本</dt><dd class="mono">{{ data.kernel.version || '未知' }}</dd></div><div><dt>上游提交</dt><dd class="mono">{{ data.kernel.upstreamCommit || '未知' }}</dd></div><div><dt>CLI 版本</dt><dd class="mono">{{ data.kernel.cliVersion || '未知' }}</dd></div></dl><p class="panel-note">内核版本随部署固定。更换版本前需要验证客户端协议与调用行为。</p></section></template>
</template>
